	if ( ! isset( $icons[ $name ] ) ) {
		return '';
	}
	list( $kind, $body ) = $icons[ $name ];
	$a11y                = '' === $label ? 'aria-hidden="true" focusable="false"' : 'role="img" aria-label="' . esc_attr( $label ) . '"';
	$paint               = 'fill' === $kind ? 'fill="currentColor"' : 'fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"';
	return sprintf( '<svg class="tw-icon tw-icon--%1$s" width="%2$d" height="%2$d" viewBox="0 0 24 24" %3$s %4$s>%5$s</svg>', esc_attr( $name ), $size, $paint, $a11y, $body );
